    return True

def find_pattern(filenames, to_delete):
    n = len(filenames)
    m = len(to_delete)

    if m == 0:
        return "No"

    # Start with the first file to be deleted
    pattern = list(filenames[to_delete[0] - 1])

    # Compare with other files to be deleted and construct the pattern
    for index in to_delete[1:]:
        current_file = filenames[index - 1]
        for i in range(len(current_file)):
            if pattern[i] != current_file[i]:
                pattern[i] = '?'

    # Check if the constructed pattern matches all files to be deleted
    for index in to_delete:
        if not matches_pattern(filenames[index - 1], ''.join(pattern)):
            return "No"

    # Check if the pattern does not match any file not to be deleted
    for i in range(n):
        if i + 1 not in to_delete:
            if matches_pattern(filenames[i], ''.join(pattern)):
                return "No"

    return "Yes\n" + ''.join(pattern)

